import {S,term as T,step as P,check as Q,task as A,lesson as L} from './shared.js';
export default [
L(4,1,{
 title:'训练不成功时：按顺序排查，而不是乱调参数',summary:'建立一条从数据、前向、损失到更新的检查链，并用极小数据验证程序能否学会。',prerequisites:['w3-l2','w1-l3'],
 terms:[T('过拟合小样本测试','刻意让模型反复学习少量样本，检查训练链路是否有能力拟合它们。','先用 8 条简单样本，不把这次成绩当成泛化成绩。'),T('非有限值','NaN 或无穷等无法作为正常损失或梯度继续使用的数值。','对非法概率取对数、数值溢出都可能产生问题。'),T('梯度范数','把一组梯度的整体大小汇总成一个数。','全局二范数相当于把所有梯度平方求和再开方。'),T('可证伪假设','能通过某项观察被证明不成立的解释。','“标签错位导致失败”可以通过逐位置打印输入和目标检查。')],
 sections:[P('第 1 步：先确认数据真的符合任务','取一条失败样本，把原始内容、处理后输入、目标和有效监督位置全部展示出来。检查单位、顺序、补齐和目标右移。你熟悉的数据流水线知识在这里比直接尝试十个学习率更有用。','如果图像、文本和动作存在配对，检查它们是不是同一时刻、同一轨迹。数据都能加载并不代表配对正确。先人工检查少量完整样本，再统计大规模分布。'),P('第 2 步：确认损失真的反映你想学的内容','检查预测与标签形状是否一致、标签编号是否合法、被忽略的位置是否正确。把一个明确的正确预测和错误预测分别喂给损失，确认正确预测损失更小。','记录损失的分子、分母和计量单位。若分母包含很多补齐位置，日志数字可能很好看，但有效目标上的错误并没有减少。'),P('第 3 步：确认参数真的被更新','对一个已知可训练参数，保存更新前的值，计算梯度并执行更新，再比较前后差异。若没有变化，检查是否被冻结、是否进入优化器，以及是否中途断开了计算图。','梯度为 None 表示没有得到该参数的梯度；梯度为 0 是得到了零值，原因可能不同。损失有限但梯度异常时，应继续检查运算和精度，而不是立即归因于数据量不够。'),P('第 4 步：让模型先学会很少几道题','固定 8 条简单样本，重复训练，暂时降低随机增强和正则影响。若连这些都拟合不了，优先怀疑实现、优化或模型表达能力。若能拟合，再扩大数据检查泛化。','这个测试成功只说明链路有基本学习能力。8 条样本上的低 loss 不能证明数据划分正确，也不能证明真实任务已解决。'),P('第 5 步：每次只验证一个解释','如果怀疑学习率过大，保持数据、初始化与预算不变，只修改学习率。如果怀疑标签错位，先构造一条可人工验证的数据。修复后保留出错样本，作为以后修改的检查材料。','不要把“数据问题”“模型问题”作为排查终点。改写成可检查的问题：哪些样本、哪个字段、哪个维度、哪个步骤出现了什么不符合预期的现象。')],
 worked:{title:'loss 完全不变的三条候选解释',steps:['候选一：参数没更新。检查更新前后 w。','候选二：输入和目标错配。打印并手算一条样本。','候选三：学习率太小。确认梯度非零，再固定其他条件比较两种学习率。','按检查成本从低到高执行，不同时改三项。'],takeaway:'诊断要把猜测变成检查，并明确什么结果会否定猜测。'},
 example:{code:'import math\nlosses = [3.0, 2.0, float("nan"), 1.0]\nfor index, loss in enumerate(losses):\n    if not math.isfinite(loss):\n        print("stop at", index, "inspect this batch")\n        break\nelse:\n    print("all finite")',output:'stop at 2 inspect this batch',explanation:'第一时间定位异常批次，比训练结束后再猜测更有效。这个检查只发现异常，不解释根因。'},
 checks:[Q('8 条样本被拟合得很好，能证明新样本表现也好吗？','区分拟合测试与独立评测。','不能。它只是排除部分训练链路问题，泛化还要用独立数据检查。',3),Q('有 NaN 时，只增加梯度裁剪是否足够？','想想错误是否发生在梯度计算之前。','不够。需要检查损失输入、运算、精度和数据；裁剪不是对 NaN 根因的修复。',2)],
 practice:{title:'制造一个故障，再留下修复证据',steps:[A('在第一周示例里注释权重更新，记录现象。','loss 不变，权重前后相同，证据支持“没有更新”。','不要只说“模型太小”，先检查更新是否执行。'),A('恢复更新，只把学习率设为 1。','权重确实改变，但误差发散，原因与上一故障不同。','从相同初始化重新开始。'),A('写一份“现象→假设→检查→修复→复测”记录。','别人可以用你的步骤重现问题和修复。','附上具体数值或输出，不只写结论。')]},sources:[S.torch,S.ce]
}),
L(4,2,{
 title:'训练工程入门：批量、显存、精度和多卡',summary:'先算清一次更新看了多少样本，再理解梯度累积与分布式训练分别解决什么问题。',prerequisites:['w1-l2','w3-l2'],
 terms:[T('micro-batch 微批次','一次前向和反向实际放入的样本。','显存只能装 4 条，就先计算这 4 条的梯度。'),T('梯度累积','把多个微批次的梯度合并后再更新一次参数。','连续处理 4 个微批次，最后执行一次 optimizer.step。'),T('混合精度 mixed precision','训练中结合不同数值精度计算，以改变速度、显存和数值行为。','部分计算用 BF16，某些统计或权重状态保留更高精度；具体取决于实现。'),T('DDP 与 FSDP','DDP 通常让各卡保留完整模型并同步梯度；FSDP 将模型相关状态分片保存。','前者主要划分数据，后者进一步降低单卡的部分存储压力。'),T('吞吐 throughput','单位时间处理的有效工作量。','有效 token/秒比只看每步秒数更适合不同长度的批次比较。')],
 sections:[P('第 1 步：先计算有效批量','若每卡 micro-batch=4，累积 8 次，有 2 张数据并行卡，一次更新通常覆盖 4×8×2=64 条样本。前提是每卡样本不同，并且梯度正确归一化。','增大累积次数不会自动让单条序列更长，也不会让模型记住更多历史。它改变一次更新合并多少监督，与记忆长度是不同问题。'),P('第 2 步：按正确单位平均梯度','一个微批次只有 2 个有效目标，另一个有 10 个。把两份“平均 loss”直接再平均，会给这两个微批次相同权重，而不是给 12 个目标相同权重。','若想按有效目标平均，应先累计 loss 总和与目标数，或对每个微批次梯度施加相应权重。数据并行框架可能还会平均梯度，需要理解组合后实际缩放。'),P('第 3 步：显存里不只有权重','除了权重，还有梯度、优化器状态、中间激活和临时工作区。激活是为了计算后续梯度而保留的中间结果；序列变长时，它们可能成为主要开销。','激活重算用重新执行部分前向来换内存；混合精度用较少字节表示部分数值，但可能改变数值稳定性。先测量峰值和耗时，再决定哪种方法值得使用。'),P('第 4 步：理解多卡的额外成本','DDP 需要同步梯度；FSDP 分片后需要在合适时机收集或交换状态。通信与数据加载都占时间，所以增加 GPU 不保证每个任务更快。小模型尤其可能被固定开销主导。','先建立单卡正确基线，再测多卡吞吐。记录有效目标数、精度、序列长度、累积次数和通信环境，才能解释速度差异。H20 的优化也要围绕这份测量，而不是只复制某个设置。')],
 worked:{title:'两个不等长微批次应该怎样平均',steps:['批次 A：损失总和 4，有效目标 2，平均为 2。','批次 B：损失总和 10，有效目标 10，平均为 1。','按批次再平均：(2+1)/2=1.5。','按目标平均：(4+10)/(2+10)=1.1667。你必须先决定想优化哪一种目标。'],takeaway:'梯度累积是否等价于大批次，取决于计算和归一化契约。'},
 example:{code:'parts = [(4.0, 2), (10.0, 10)]\nmean_of_batches = sum(total/n for total,n in parts) / len(parts)\nmean_of_targets = sum(total for total,n in parts) / sum(n for total,n in parts)\nprint("batch mean", mean_of_batches)\nprint("target mean", round(mean_of_targets, 4))\nprint("effective batch", 4*8*2)',output:'batch mean 1.5\ntarget mean 1.1667\neffective batch 64',explanation:'这里用 loss 数值解释平均方式；实际训练时相同的权重也会影响梯度。'},
 checks:[Q('累积 8 个微批次是否意味着模型能看到 8 倍长的单条上下文？','区分不同样本的梯度与同一序列的信息。','不意味着。累积合并更新信号，不会自动把这些输入连接成可读取的长历史。',0),Q('为什么两卡可能比一卡更慢？','把计算之外的工作也算进时间。','通信、同步、数据加载以及小任务固定开销可能超过并行收益，需要测量。',3)],
 practice:{title:'算清预算，再测一项资源',steps:[A('完成加权梯度累积练习。','不等长微批次也能得到按目标平均的结果。','不能无条件除以微批次数。'),A('为 tiny_lm 记录参数量、batch、设备、步数与总耗时。','能计算至少一种明确吞吐指标。','CPU 上不报告虚构的 GPU 显存。'),A('只改变 batch，比较训练耗时和验证结果。','区分每步速度变化与总训练预算变化。','batch 变化后相同步数会消费不同数据量。')]},links:[{label:'加权累积练习',href:'#/code/weighted-accumulation'}],sources:[S.fsdp,S.adam]
}),
L(4,3,{
 title:'评测名字怎样读：MMLU、MMMU、MMStar 与指标',summary:'先区分题集和评分规则，再用四道题算一次分数，理解为什么百分比不能脱离评测协议。',prerequisites:['w1-l3','w2-l1'],
 terms:[T('benchmark 评测基准','一组任务、数据和评测约定，用来检查某些能力。','题集考什么，与最后用什么分数汇总，是不同问题。'),T('metric 指标','把预测和目标转成数值的规则。','准确率、均方误差、成功率都是指标。'),T('MMLU','涵盖多个学科的文本选择题基准，常按准确率评测。','它主要检查这些题上的表现，不是机器人闭环测试。'),T('MMMU','涉及多个学科、需要结合多模态信息的理解基准。','部分问题包含图表、图片及学科知识。'),T('MMStar','用于检验多模态理解的视觉语言基准，设计关注视觉依赖等问题。','应结合具体版本与评测协议理解分数，不能当成通用“智能值”。')],
 sections:[P('第 1 步：先问考卷，再问评分','把 benchmark 想成试卷和考试规则，把 metric 想成计分方法。两个试卷都用准确率，但考察能力可能完全不同。说“MMMU 是一种准确率算法”混淆了这两层。','面对分数先问：题目是什么模态？输出是选项、自由回答还是动作？怎样判断正确？是否允许额外工具、检索或多次尝试？'),P('第 2 步：亲手算一次准确率','四道题，正确三道，准确率是 75%。如果只有四道题，多错一道就从 75% 变成 50%。小样本上的分数变化可能很大，不能把一点波动直接当作方法优劣。','还要看每个子任务。例如总体上升但某个关键场景下降，可能是数据权重不同造成。记录样本数、子集和失败案例，避免平均值隐藏问题。'),P('第 3 步：固定提问与答案提取方式','提示模板、给出的示例、采样设置和答案解析都可能改变选择题分数。模型输出“答案是 B”，若解析器只接受裸字母，评分可能失真。','检查评测程序时，保留原始输出和解析后的答案，并人工复查一小批。还要检查评测题是否混入训练数据，否则高分可能来自接触过答案。'),P('第 4 步：把基准放回你的岗位目标','理解世界模型的人应同时关心未来预测误差、动作条件一致性和闭环成功率。MMLU/MMMU/MMStar 可说明相关理解能力，但不直接证明动态预测或机器人控制可靠。','本周阶段检查要求你能追踪训练数据、损失和参数更新，并解释一个评测的边界。遇到不会的术语，回到已链接课文；不要求靠背诵排行榜证明能力。')],
 worked:{title:'总体分数相同，错误分布可以不同',steps:['方法 A 的四题结果为 [对,对,对,错]。','方法 B 的结果为 [错,对,对,对]，准确率也为 75%。','若第一题对应关键安全场景，两种结果的任务意义不同。','因此保留逐题记录和子集统计，再给出总体分数。'],takeaway:'分数回答的是具体评测问题，不能脱离题目和协议解释。'},
 example:{code:'gold = ["A", "C", "B", "D"]\npredicted = ["A", "C", "A", "D"]\ncorrect = [p == y for p,y in zip(predicted, gold)]\nprint("per item", correct)\nprint("accuracy", sum(correct) / len(correct))',output:'per item [True, True, False, True]\naccuracy 0.75',explanation:'这是准确率计算示例，四个字母并不是任何真实基准的题目或答案。'},
 checks:[Q('MMLU 和准确率分别属于哪一层？','一个规定考什么，一个规定怎么算分。','MMLU 是基准，准确率是指标；同一种指标可用于不同基准。',0),Q('MMMU 分数高，是否能直接证明机器人会可靠执行动作？','比较题目输出与机器人任务输出。','不能。多模态答题与动作闭环是不同评测对象，仍需动作和环境实验。',3)],
 practice:{title:'给一项分数写清适用范围',steps:[A('选择一个基准条目，记录输入、输出和计分规则。','至少区分基准名称与指标名称。','先读官方任务介绍，再读排行榜数字。'),A('给准确率示例增加一条错误答案，观察分数变化。','理解分母和样本数影响。','预测和目标数量必须对应，不能漏评难题。'),A('完成第 1–4 周阶段测验，并回顾一份故障修复记录。','能用证据说明训练做了什么、分数证明了什么。','阶段题都来自已学课程，未过的概念返回对应课文。')]},sources:[S.mmlu,S.mmmu,S.mmstar]
})];
